import theme from './theme';
import { useEffect } from 'react';
import { useDispatch } from 'react-redux';
import { ThemeProvider } from '@mui/material';
import { Routes, Route } from 'react-router-dom';
import CssBaseline from '@mui/material/CssBaseline';

// Pages
import News from './pages/News';
import Home from './pages/Home';
import About from './pages/About';
import Events from './pages/Events';
import History from './pages/History';
import Contact from './pages/Contact';
import Gallery from './pages/Gallery';
import NewsDetail from './pages/NewsDetail';
import Governance from './pages/Governance';
import Regulations from './pages/Regulations';
import GalleryDetails from './pages/GalleryDetails';
import WhatIsGymkhana from './pages/WhatIsGymkhana';

// Components
import Navbar from './components/Navbar';
import Footer from './components/Footer';
import ScrollToTop from './components/ScrollToTop';
import SmoothScroll from './components/SmoothScroll';

import { fetchLatestNews } from './redux/newsSlice';
import { fetchGalleryItems } from './redux/gallerySlice';
import { fetchUpcomingEvents } from './redux/eventsSlice';
import { fetchChampionshipStats } from './redux/statsSlice';

function App() {
  const dispatch = useDispatch();

  useEffect(() => {
    dispatch(fetchLatestNews());
    dispatch(fetchGalleryItems());
    dispatch(fetchUpcomingEvents());
    dispatch(fetchChampionshipStats());
  }, [dispatch]);

  return (
    <ThemeProvider theme={theme}>
      <Navbar />
      <Routes>
        <Route path="/" element={<Home />} />
        <Route path="/about" element={<About />} />
        <Route path="/what-is-gymkhana" element={<WhatIsGymkhana />} />
        <Route path="/events" element={<Events />} />
        <Route path="/gallery" element={<Gallery />} />
        <Route path="/gallery/:category" element={<Gallery />} />
        <Route path="/gallery-details/:category" element={<GalleryDetails />} />
        <Route path="/news" element={<News />} />
        <Route path="/news/:id" element={<NewsDetail />} />
        <Route path="/governance" element={<Governance />} />
        <Route path="/contact" element={<Contact />} />
        <Route path="/history" element={<History />} />
        <Route path="/regulations" element={<Regulations />} />
        <Route path="/regulations/:categoryId" element={<Regulations />} />
      </Routes>
      <Footer />
      <ScrollToTop />
      <SmoothScroll />
      <CssBaseline />
    </ThemeProvider>
  );
}

export default App;
