import React, { useEffect, useState } from 'react';
import {
    Box,
    Container,
    Typography,
    Chip,
    CircularProgress,
    Stack,
    Button,
    Breadcrumbs,
    Link as MuiLink,
} from '@mui/material';
import AccessTimeIcon from '@mui/icons-material/AccessTime';
import ArrowBackIcon from '@mui/icons-material/ArrowBack';
import { format } from 'date-fns';
import { useNavigate, useParams, Link as RouterLink } from 'react-router-dom';
import { getNewsById } from '../services/api';

const NewsDetail = () => {
    const { id } = useParams();
    const navigate = useNavigate();
    const [article, setArticle] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    useEffect(() => {
        const fetchArticle = async () => {
            try {
                const data = await getNewsById(id);
                if (!data || !data.id) {
                    setError('We could not find that news item.');
                } else {
                    setArticle(data);
                }
            } catch (err) {
                console.error('Error fetching news article:', err);
                setError('Something went wrong while loading this article.');
            } finally {
                setLoading(false);
            }
        };

        fetchArticle();
    }, [id]);

    const renderContent = () => {
        if (loading) {
            return (
                <Stack spacing={2} alignItems="center" sx={{ py: 12 }}>
                    <CircularProgress color="primary" />
                    <Typography variant="body1">Loading story…</Typography>
                </Stack>
            );
        }

        if (error) {
            return (
                <Stack spacing={3} alignItems="center" sx={{ py: 12 }}>
                    <Typography variant="h6" align="center">
                        {error}
                    </Typography>
                    <Button
                        variant="contained"
                        color="secondary"
                        startIcon={<ArrowBackIcon />}
                        onClick={() => navigate('/news')}
                    >
                        Back to News
                    </Button>
                </Stack>
            );
        }

        const formattedDate = article?.date
            ? format(new Date(article.date), 'dd MMM yyyy')
            : '';

        return (
            <>
                <Breadcrumbs sx={{ mb: 3 }} separator="/">
                    <MuiLink component={RouterLink} to="/news" color="inherit">
                        News
                    </MuiLink>
                    <Typography color="text.primary">{article.title}</Typography>
                </Breadcrumbs>

                <Typography
                    variant="h1"
                    sx={{
                        fontFamily: 'Bebas Neue',
                        fontSize: { xs: '2.5rem', md: '4rem' },
                        lineHeight: 1.1,
                        mb: 2,
                    }}
                >
                    {article.title}
                </Typography>

                <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2} sx={{ mb: 4 }}>
                    <Chip
                        icon={<AccessTimeIcon sx={{ fontSize: 18 }} />}
                        label={formattedDate}
                        sx={{
                            bgcolor: '#0A2342',
                            color: 'white',
                            '& .MuiChip-icon': { color: 'white' },
                            letterSpacing: 1,
                        }}
                    />
                    {article.updatedAt && article.updatedAt !== article.date && (
                        <Chip
                            label={`Updated ${format(new Date(article.updatedAt), 'dd MMM yyyy')}`}
                            sx={{ borderColor: 'primary.main', borderWidth: 1, borderStyle: 'solid' }}
                            variant="outlined"
                        />
                    )}
                </Stack>

                {article.imageUrl && (
                    <Box
                        sx={{
                            position: 'relative',
                            borderRadius: 4,
                            overflow: 'hidden',
                            mb: 5,
                            boxShadow: '0 20px 45px rgba(10, 35, 66, 0.3)',
                        }}
                    >
                        <Box
                            component="img"
                            src={article.imageUrl}
                            alt={article.title}
                            sx={{
                                width: '100%',
                                maxHeight: 520,
                                objectFit: 'cover',
                                display: 'block',
                            }}
                        />
                        <Box
                            sx={{
                                position: 'absolute',
                                inset: 0,
                                background: 'linear-gradient(180deg, rgba(0,0,0,0.1) 0%, rgba(0,0,0,0.65) 100%)',
                                opacity: 0,
                                transition: 'opacity 0.4s ease',
                                '&:hover': { opacity: 1 },
                            }}
                        />
                    </Box>
                )}

                <Box
                    sx={{
                        bgcolor: 'rgba(10, 35, 66, 0.04)',
                        borderRadius: 3,
                        p: { xs: 3, md: 4 },
                        lineHeight: 1.8,
                        fontSize: '1.1rem',
                    }}
                >
                    {article.content?.split('\n').filter(Boolean).map((paragraph, index) => (
                        <Typography
                            key={index}
                            variant="body1"
                            sx={{ mb: 3, fontWeight: 300, letterSpacing: 0.2 }}
                        >
                            {paragraph}
                        </Typography>
                    ))}
                </Box>
            </>
        );
    };

    return (
        <Box sx={{ bgcolor: 'background.default', minHeight: '100vh' }}>
            <Container maxWidth="md" sx={{ py: 8 }}>
                <Button
                    variant="text"
                    startIcon={<ArrowBackIcon />}
                    sx={{ mb: 3 }}
                    onClick={() => navigate(-1)}
                >
                    Back
                </Button>
                {renderContent()}
            </Container>
        </Box>
    );
};

export default NewsDetail;
