import axios from 'axios';

const API_URL = 'https://gmk-web-api.chronopulse.com/api';
// const API_URL = 'http://localhost:5001/api';


const api = axios.create({
  baseURL: API_URL,
  headers: {
    'Content-Type': 'application/json'
  }
});

// Slider APIs
export const getSliderItems = async () => {
  const response = await api.get('/slider');
  return response.data;
};

// News APIs
export const getLatestNews = async (limit = 5) => {
  const response = await api.get(`/news/latest?limit=${limit}`);
  return response.data;
};

export const getNewsById = async (id) => {
  const response = await api.get(`/news/${id}`);
  return response.data;
};

// Events APIs
export const getUpcomingEvents = async (limit) => {
  const response = limit ? await api.get(`/events?limit=${limit}`) : await api.get(`/events`);
  var eventList = Array.isArray(response.data) ? response.data : [];
  
  const today = new Date();
  today.setHours(0, 0, 0, 0);

  eventList.sort((a, b) => {
    const dateA = new Date(a.date);
    const dateB = new Date(b.date);
    const isAFuture = dateA >= today;
    const isBFuture = dateB >= today;

    if (isAFuture && !isBFuture) return -1;
    if (!isAFuture && isBFuture) return 1;

    return Math.abs(dateA - today) - Math.abs(dateB - today);
  });
  
  return eventList;
};

