import { createAsyncThunk, createSlice } from '@reduxjs/toolkit';
import { getAllContacts } from '../services/api';
import { extractMapUrl } from '../utils/mapUtils';

/**
 * Async thunk to fetch contact information from the backend.
 * Normalizes the response data by parsing the socialMedia JSON string.
 */
export const fetchContacts = createAsyncThunk(
    'contact/fetchContacts',
    async (_, { rejectWithValue }) => {
        try {
            const data = await getAllContacts();
            const contact = Array.isArray(data) ? data[0] : data;

            if (contact) {
                // Normalize socialMedia data
                let socialMedia = {};
                if (contact.socialMedia) {
                    try {
                        socialMedia = typeof contact.socialMedia === 'string'
                            ? JSON.parse(contact.socialMedia)
                            : contact.socialMedia;
                    } catch (e) {
                        console.error('Failed to parse socialMedia JSON:', e);
                    }
                }

                // Ensure all expected fields exist to prevent component-level errors
                return {
                    ...contact,
                    socialMedia: {
                        facebook: socialMedia.facebook || contact.facebook || contact.facebook_url || '',
                        instagram: socialMedia.instagram || contact.instagram || contact.instagram_url || '',
                        youtube: socialMedia.youtube || contact.youtube || contact.youtube_url || '',
                        twitter: socialMedia.twitter || contact.twitter || ''
                    },
                    address: contact.address || '',
                    phone: contact.phone || contact.phone_number || '',
                    email: contact.email || '',
                    mapUrl: extractMapUrl(contact?.mapUrl || contact?.address || '')
                };
            }
            return null;
        } catch (error) {
            return rejectWithValue(error?.message || 'Failed to fetch contact information');
        }
    }
);

const contactSlice = createSlice({
    name: 'contact',
    initialState: {
        data: null,
        status: 'idle',
        error: null,
    },
    reducers: {},
    extraReducers: (builder) => {
        builder
            .addCase(fetchContacts.pending, (state) => {
                state.status = 'loading';
                state.error = null;
            })
            .addCase(fetchContacts.fulfilled, (state, action) => {
                state.status = 'succeeded';
                state.data = action.payload;
            })
            .addCase(fetchContacts.rejected, (state, action) => {
                state.status = 'failed';
                state.error = action.payload || action.error.message;
            });
    },
});

export const selectContactInfo = (state) => state.contact.data;
export const selectContactStatus = (state) => state.contact.status;
export const selectContactError = (state) => state.contact.error;

export default contactSlice.reducer;
