import React, { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import {
  Box,
  Container,
  Typography,
  Card,
  Grid,
  IconButton,
  Accordion,
  AccordionSummary,
  AccordionDetails,
} from '@mui/material';
import DescriptionIcon from '@mui/icons-material/Description';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import { motion } from 'framer-motion';
import { getRegulationCategories, getRegulations } from '../services/api';

function RegulationCard({ title, documentUrl, year }) {
  // Convert relative URL to absolute URL if needed
  const fullDocumentUrl = documentUrl?.startsWith('http') 
    ? documentUrl 
    : `https://gmk-web-api.chronopulse.com${documentUrl}`;
  return (
    <motion.div
      whileHover={{ scale: 1.02 }}
      whileTap={{ scale: 0.98 }}
    >
      <Card
        sx={{
          p: 2,
          height: '100%',
          display: 'flex',
          alignItems: 'center',
          bgcolor: 'background.paper',
          '&:hover': {
            boxShadow: 6,
            '& .download-icon': {
              color: 'primary.main',
            },
          },
        }}
      >
        <Box sx={{ flexGrow: 1 }}>
          <Typography variant="subtitle1" component="h3">
            {title}
          </Typography>
        </Box>
        <IconButton 
          className="download-icon"
          href={fullDocumentUrl}
          target="_blank"
          sx={{ 
            color: 'text.secondary',
            transition: 'color 0.2s',
          }}
        >
          <DescriptionIcon />
        </IconButton>
      </Card>
    </motion.div>
  );
}

function RegulationSection({ category, regulations }) {
  return (
    <Accordion defaultExpanded>
      <AccordionSummary
        expandIcon={<ExpandMoreIcon />}
        sx={{
          backgroundColor: 'primary.main',
          color: 'white',
          '& .MuiAccordionSummary-expandIconWrapper': {
            color: 'white'
          }
        }}
      >
        <Typography variant="h6">{category.name}</Typography>
      </AccordionSummary>
      <AccordionDetails>
        {Array.isArray(category.subCategories) && category.subCategories.map((subCat) => {
          const subCatRegulations = regulations.filter(
            r => r.categoryId === category.id && r.subCategory === subCat.name
          );

          if (subCatRegulations.length === 0) return null;

          return (
            <Box key={subCat.name} sx={{ mb: 4 }}>
              <Typography
                variant="h6"
                sx={{
                  color: 'primary.main',
                  mb: 2,
                  borderBottom: '2px solid',
                  borderColor: 'primary.main',
                  pb: 1,
                }}
              >
                {subCat.name}
              </Typography>
              <Grid container spacing={3}>
                {subCatRegulations.map((regulation) => (
                  <Grid item xs={12} md={6} key={regulation.id}>
                    <RegulationCard {...regulation} />
                  </Grid>
                ))}
              </Grid>
            </Box>
          );
        })}
      </AccordionDetails>
    </Accordion>
  );
}

function Regulations() {
  const { categoryId } = useParams();
  const [categories, setCategories] = useState([]);
  const [regulations, setRegulations] = useState([]);
  const [selectedCategory, setSelectedCategory] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [categoriesData, regulationsData] = await Promise.all([
          getRegulationCategories(),
          getRegulations()
        ]);

        // Parse subCategories from string to array if needed
        const processedCategories = categoriesData.map(cat => ({
          ...cat,
          subCategories: Array.isArray(cat.subCategories)
            ? cat.subCategories
            : typeof cat.subCategories === 'string'
              ? JSON.parse(cat.subCategories)
              : []
        }));

        setCategories(processedCategories);
        setRegulations(regulationsData);

        if (categoryId) {
          const category = processedCategories.find(cat => cat.id === categoryId);
          setSelectedCategory(category || null);
        }
      } catch (error) {
        console.error('Error fetching data:', error);
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, [categoryId]);

  return (
    <Container maxWidth="lg" sx={{ py: 4 }}>
      {loading ? (
        <Box sx={{ display: 'flex', justifyContent: 'center', py: 4 }}>
          <Typography>Loading...</Typography>
        </Box>
      ) : (
        <>
          <Box sx={{ mb: 4 }}>
            <Typography variant="h4" component="h1" gutterBottom>
              {selectedCategory ? selectedCategory.name : 'All Regulations'}
            </Typography>
          </Box>
          {(categoryId ? categories.filter(cat => cat.id.toString() === categoryId.toString()) : categories).map((category) => (
            <RegulationSection
              key={category.id}
              category={category}
              regulations={regulations.filter(r => r.categoryId === category.id)}
            />
          ))}
        </>
      )}
    </Container>
  );
}

export default Regulations;
