import {
  Box,
  Button,
  Container,
  Typography,
} from '@mui/material';
import { useEffect } from 'react';
import { motion, useAnimation } from 'framer-motion';
import { useInView } from 'react-intersection-observer';



function AnimatedSection({ children, delay = 0 }) {
  const controls = useAnimation();
  const [ref, inView] = useInView({
    triggerOnce: true,
    threshold: 0.1,
  });

  useEffect(() => {
    if (inView) {
      controls.start({
        opacity: 1,
        y: 0,
        transition: { duration: 0.8, delay },
      });
    }
  }, [controls, inView, delay]);

  return (
    <motion.div
      ref={ref}
      initial={{ opacity: 0, y: 20 }}
      animate={controls}
    >
      {children}
    </motion.div>
  );
}
const Register = () => {
  return (
    <Box
      sx={{
        py: 8,
        background: `linear-gradient(rgba(0, 31, 63, 0.9), rgba(0, 31, 63, 0.9)), url('/images/3c93e6c3-cff2-40ec-bf53-e9cbf73f0f9c.jpg')`,
        backgroundSize: 'cover',
        backgroundPosition: 'center',
        backgroundAttachment: 'fixed',
        color: 'white',
        position: 'relative',
        overflow: 'hidden',
        '&::after': {
          content: '""',
          position: 'absolute',
          bottom: 0,
          left: 0,
          right: 0,
          height: '5px',
        },
      }}
    >
      <Container maxWidth="lg">
        <AnimatedSection delay={0.6}>
          <motion.div
            whileHover={{ scale: 1.02 }}
            transition={{ type: 'spring', stiffness: 400, damping: 10 }}
          >
            <Box sx={{ textAlign: 'center' }}>
              <Typography variant="h2" sx={{ mb: 3, fontFamily: 'Bebas Neue' }}>
                Ready to Join the Championship?
              </Typography>
              <Typography variant="h5" sx={{ mb: 4, fontWeight: 300 }}>
                Register now and be part of the most exciting motorsport event in Asia
              </Typography>
              <motion.div whileHover={{ scale: 1.1 }} whileTap={{ scale: 0.95 }}>
                <Button
                  variant="contained"
                  color="secondary"
                  size="large"
                  sx={{
                    fontWeight: 'bold',
                    px: 4,
                    py: 1.5,
                    fontSize: '1.2rem',
                    borderRadius: '30px',
                    background: 'linear-gradient(45deg, #FFD700, #FF4081)',
                    boxShadow: '0 4px 15px rgba(255, 215, 0, 0.3)',
                    '&:hover': {
                      background: 'linear-gradient(45deg, #FF4081, #FFD700)',
                    },
                  }}
                >
                  Register Now
                </Button>
              </motion.div>
            </Box>
          </motion.div>
        </AnimatedSection>
      </Container>
    </Box>
  );
};

export default Register;
